create type public.preparation_status as enum ('pending','in_progress','completed');
create type public.delivery_status as enum ('scheduled','for_delivery','completed','cancelled');
alter table public.order_items add column preparation_status public.preparation_status not null default 'pending';
alter table public.order_items add column prepared_by uuid references public.profiles(id) on delete restrict;
alter table public.order_items add column prepared_at timestamptz;
create table public.deliveries (id uuid primary key default gen_random_uuid(),order_id uuid not null unique references public.orders(id) on delete restrict,assigned_driver_id uuid references public.profiles(id) on delete restrict,scheduled_date date not null,scheduled_time time,status public.delivery_status not null default 'scheduled',notes text,completed_at timestamptz,cancelled_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint deliveries_completed_timestamp check ((status='completed' and completed_at is not null) or status <> 'completed'));
create index deliveries_driver_date_idx on public.deliveries(assigned_driver_id,scheduled_date);
create trigger deliveries_set_updated_at before update on public.deliveries for each row execute procedure public.set_updated_at();
alter table public.deliveries enable row level security;
revoke all on public.deliveries from anon, authenticated;
grant select,insert,update on public.deliveries to authenticated;
create policy "staff_read_relevant_deliveries" on public.deliveries for select to authenticated using (public.has_app_role(array['administrator','administrative_staff']::public.profile_role[]) or (public.has_app_role(array['delivery_staff']::public.profile_role[]) and assigned_driver_id=auth.uid()));
create policy "management_write_deliveries" on public.deliveries for all to authenticated using (public.has_app_role(array['administrator','administrative_staff']::public.profile_role[])) with check (public.has_app_role(array['administrator','administrative_staff']::public.profile_role[]));
create policy "driver_update_assigned_delivery" on public.deliveries for update to authenticated using (public.has_app_role(array['delivery_staff']::public.profile_role[]) and assigned_driver_id=auth.uid() and status in ('scheduled','for_delivery')) with check (public.has_app_role(array['delivery_staff']::public.profile_role[]) and assigned_driver_id=auth.uid());
create function public.update_preparation_status(p_item_id uuid,p_status public.preparation_status) returns void language plpgsql security definer set search_path=public as $$ declare v_order uuid; begin if not public.has_app_role(array['administrator','administrative_staff','fulfillment_staff']::public.profile_role[]) then raise exception 'You do not have preparation access'; end if; update public.order_items set preparation_status=p_status,prepared_by=case when p_status='completed' then auth.uid() else null end,prepared_at=case when p_status='completed' then now() else null end where id=p_item_id returning order_id into v_order; if v_order is null then raise exception 'Preparation item not found'; end if; insert into public.order_activity(order_id,user_id,action,details) values(v_order,auth.uid(),'preparation_updated',jsonb_build_object('item_id',p_item_id,'status',p_status)); if p_status='completed' and not exists(select 1 from public.order_items where order_id=v_order and preparation_status <> 'completed') then update public.orders set status='for_delivery' where id=v_order and status='for_preparation'; end if; end; $$;
grant execute on function public.update_preparation_status(uuid,public.preparation_status) to authenticated;
create function public.update_delivery_status(p_delivery_id uuid,p_status public.delivery_status) returns void language plpgsql security definer set search_path=public as $$ declare v_order uuid; begin if not (public.has_app_role(array['administrator','administrative_staff']::public.profile_role[]) or exists(select 1 from public.deliveries where id=p_delivery_id and assigned_driver_id=auth.uid() and public.has_app_role(array['delivery_staff']::public.profile_role[]))) then raise exception 'You do not have delivery access'; end if; update public.deliveries set status=p_status,completed_at=case when p_status='completed' then now() else completed_at end where id=p_delivery_id returning order_id into v_order; if v_order is null then raise exception 'Delivery not found'; end if; if p_status='for_delivery' then update public.orders set status='for_delivery' where id=v_order and status='for_preparation'; elsif p_status='completed' then update public.orders set status='completed' where id=v_order and status='for_delivery'; end if; insert into public.order_activity(order_id,user_id,action,details) values(v_order,auth.uid(),'delivery_updated',jsonb_build_object('delivery_id',p_delivery_id,'status',p_status)); end; $$;
grant execute on function public.update_delivery_status(uuid,public.delivery_status) to authenticated;
